//---------------------------------------------------------------------------
File_Mxf::~File_Mxf()
{
    #if defined(MEDIAINFO_ANCILLARY_YES)
        if (Ancillary)
        {
            for (essences::iterator Essence=Essences.begin(); Essence!=Essences.end(); ++Essence)
                for (parsers::iterator Parser=Essence->second.Parsers.begin(); Parser!=Essence->second.Parsers.end(); ++Parser)
                    if (*Parser == Ancillary)
                        *Parser = nullptr;
            delete Ancillary;
        }
    #endif //defined(MEDIAINFO_ANCILLARY_YES)
	
    for (size_t i = 0; i < AcquisitionMetadataLists.size(); i++)
        delete AcquisitionMetadataLists[ i ];
	
    AcquisitionMetadataLists.clear();
	
    for (size_t i = 0; i < AcquisitionMetadata_Sony_E201_Lists.size(); i++)
        delete AcquisitionMetadata_Sony_E201_Lists[ i ];
	
    AcquisitionMetadata_Sony_E201_Lists.clear();
    delete DolbyAudioMetadata;
    #if defined(MEDIAINFO_ADM_YES)
        delete Adm;
    #endif
}

//***************************************************************************
// Streams management
//***************************************************************************

//---------------------------------------------------------------------------
void File_Mxf::Streams_Accept()
{
    Fill(Stream_General, 0, General_Format, "MXF");

    //Configuration
    Buffer_MaximumSize=64*1024*1024; //Some big frames are possible (e.g YUV 4:2:2 10 bits 1080p, 4K)
    File_Buffer_Size_Hint_Pointer=Config->File_Buffer_Size_Hint_Pointer_Get();
}

//---------------------------------------------------------------------------
void File_Mxf::Streams_Fill()
{
    for (essences::iterator Essence=Essences.begin(); Essence!=Essences.end(); ++Essence)
        for (parsers::iterator Parser=Essence->second.Parsers.begin(); Parser!=Essence->second.Parsers.end(); ++Parser)
            Fill(*Parser);
}

//---------------------------------------------------------------------------
// Minimal JSON reader, flattening to "Parent_Child" / "Parent_0_Child" names
namespace Arri
{
    typedef std::vector<std::pair<std::string, Ztring> > fields;

    static void Json_Skip(const char*& p, const char* End)
    {
        while (p<End && (*p==' ' || *p=='\t' || *p=='\r' || *p=='\n'))
            p++;
    }

    static bool Json_Hex4(const char* p, int32u& Value)
    {
        Value=0;
        for (int i=0; i<4; i++)
        {
            char c=p[i];
            Value<<=4;
            if (c>='0' && c<='9') Value|=c-'0';
            else if (c>='a' && c<='f') Value|=c-'a'+10;
            else if (c>='A' && c<='F') Value|=c-'A'+10;
            else return false;
        }
        return true;
    }

    static void Json_Utf8(int32u C, std::string& Out)
    {
        if (C<0x80)
            Out+=(char)C;
        else if (C<0x800)
        {
            Out+=(char)(0xC0|(C>>6));
            Out+=(char)(0x80|(C&0x3F));
        }
        else if (C<0x10000)
        {
            Out+=(char)(0xE0|(C>>12));
            Out+=(char)(0x80|((C>>6)&0x3F));
            Out+=(char)(0x80|(C&0x3F));
        }
        else
        {
            Out+=(char)(0xF0|(C>>18));
            Out+=(char)(0x80|((C>>12)&0x3F));
            Out+=(char)(0x80|((C>>6)&0x3F));
            Out+=(char)(0x80|(C&0x3F));
        }
    }

    static bool Json_String(const char*& p, const char* End, std::string& Out)
    {
        if (p>=End || *p!='"')
            return false;
        p++;
        while (p<End && *p!='"')
        {
            if (*p!='\\')
            {
                Out+=*p++;
                continue;
            }
            if (++p>=End)
                return false;
            switch (*p)
            {
                case 'b': Out+='\b'; break;
                case 'f': Out+='\f'; break;
                case 'n': Out+='\n'; break;
                case 'r': Out+='\r'; break;
                case 't': Out+='\t'; break;
                case 'u':
                {
                    int32u C;
                    if (p+4>=End || !Json_Hex4(p+1, C))
                        return false;
                    p+=4;
                    if (C>=0xD800 && C<=0xDBFF && p+6<End && p[1]=='\\' && p[2]=='u')
                    {
                        int32u Low;
                        if (!Json_Hex4(p+3, Low) || Low<0xDC00 || Low>0xDFFF)
                            return false;
                        C=0x10000+((C-0xD800)<<10)+(Low-0xDC00);
                        p+=6;
                    }
                    Json_Utf8(C, Out);
                    break;
                }
                default: Out+=*p; //\" \\ \/
            }
            p++;
        }
        if (p>=End)
            return false;
        p++;
        return true;
    }

    static std::string Json_Name(const std::string& Prefix, std::string Key)
    {
        if (!Key.empty() && Key[0]>='a' && Key[0]<='z')
            Key[0]-=0x20;
        return Prefix.empty()?Key:Prefix+'_'+Key;
    }

    static bool Json_Value(const char*& p, const char* End, const std::string& Name, fields& Out, size_t Depth)
    {
        Json_Skip(p, End);
        if (p>=End || Depth>16)
            return false;
        switch (*p)
        {
            case '{':
            {
                p++;
                fields Items;
                for (;;)
                {
                    Json_Skip(p, End);
                    if (p<End && *p=='}')
                    {
                        p++;
                        break;
                    }
                    std::string Key;
                    if (!Json_String(p, End, Key))
                        return false;
                    Json_Skip(p, End);
                    if (p>=End || *p!=':')
                        return false;
                    p++;
                    if (!Json_Value(p, End, Json_Name(Name, Key), Items, Depth+1))
                        return false;
                    Json_Skip(p, End);
                    if (p<End && *p==',')
                    {
                        p++;
                        continue;
                    }
                    if (p>=End || *p!='}')
                        return false;
                    p++;
                    break;
                }
                //{"key": "a.b.Name", "value": x} pairs become Name=x
                if (Items.size()==2 && Items[0].first==Name+"_Key" && Items[1].first==Name+"_Value")
                {
                    std::string Key=Items[0].second.To_UTF8();
                    Out.push_back(std::make_pair(Json_Name(std::string(), Key.substr(Key.rfind('.')+1)), Items[1].second));
                }
                else
                    Out.insert(Out.end(), Items.begin(), Items.end());
                return true;
            }
            case '[':
            {
                p++;
                for (size_t i=0; ; i++)
                {
                    Json_Skip(p, End);
                    if (p<End && *p==']')
                    {
                        p++;
                        return true;
                    }
                    if (!Json_Value(p, End, Name+'_'+to_string(i), Out, Depth+1))
                        return false;
                    Json_Skip(p, End);
                    if (p<End && *p==',')
                    {
                        p++;
                        continue;
                    }
                    if (p>=End || *p!=']')
                        return false;
                    p++;
                    return true;
                }
            }
            case '"':
            {
                std::string Value;
                if (!Json_String(p, End, Value))
                    return false;
                if (Value.size()<=1024) //Blobs (e.g. base64 LUT data) are not displayed
                    Out.push_back(std::make_pair(Name, Ztring().From_UTF8(Value)));
                return true;
            }
            default:
            {
                const char* Start=p;
                while (p<End && *p!=',' && *p!='}' && *p!=']' && *p!=' ' && *p!='\t' && *p!='\r' && *p!='\n')
                    p++;
                std::string Value(Start, p);
                if (Value=="true")
                    Out.push_back(std::make_pair(Name, Ztring(__T("Yes"))));
                else if (Value=="false")
                    Out.push_back(std::make_pair(Name, Ztring(__T("No"))));
                else if (Value!="null")
                    Out.push_back(std::make_pair(Name, Ztring().From_UTF8(Value)));
                return !Value.empty();
            }
        }
    }

    static void Json_Flatten(const std::string& Json, fields& Out)
    {
        const char* p=Json.c_str();
        Json_Value(p, p+Json.size(), std::string(), Out, 0);
    }
}

